const { pathToFileURL } = require("url");
(async () => {
  let chat;
  try {
    chat = await import(pathToFileURL(require.resolve("agents/chat")).href);
  } catch (e) {
    console.error("ERROR: cannot load agents/chat: " + e.message);
    process.exit(2);
  }
  if (typeof chat.repairInterruptedToolParts !== "function") {
    console.error("ERROR: repairInterruptedToolParts is not exported");
    process.exit(2);
  }
  const messages = [
    { id: "u1", role: "user", parts: [{ type: "text", text: "deploy" }] },
    { id: "a1", role: "assistant", parts: [{ type: "tool-deploy", toolCallId: "tc1", state: "approval-responded", input: { env: "prod" }, approval: { id: "ap1", approved: true } }] },
    { id: "u2", role: "user", parts: [{ type: "text", text: "thanks" }] }
  ];
  let result;
  try {
    result = chat.repairInterruptedToolParts(messages, {
      repairPart: (p) => ({ ...p, state: "output-error", errorText: "did not run" }),
      repairApprovalResponded: true
    });
  } catch (e) {
    console.error("ERROR: repairInterruptedToolParts threw: " + e.message);
    process.exit(2);
  }
  const part = result && result.messages && result.messages[1] && result.messages[1].parts[0];
  if (!part) {
    console.error("ERROR: unexpected result " + JSON.stringify(result));
    process.exit(2);
  }
  if (part.state === "output-error" && result.removedToolCalls === 1) {
    console.log("OK: approved tool call that never ran was settled as output-error");
    process.exit(0);
  }
  if (part.state === "approval-responded" && result.removedToolCalls === 0) {
    console.error("FAIL: approved tool call that never ran stays approval-responded after a later message");
    process.exit(1);
  }
  console.error("ERROR: unexpected part state " + part.state + " removedToolCalls " + result.removedToolCalls);
  process.exit(2);
})();

